package dev.kicadvizdiff.android;

import java.io.IOException;
import java.net.URI;
import java.net.URLEncoder;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.List;
import org.json.JSONArray;
import org.json.JSONObject;

/** Provider-owned board data. Transport and credentials remain in the native host. */
final class NativeWorkBoards {
    static final class Failure extends IOException {Failure(String message){super(message);}}
    interface Transport {
        void authorize(boolean write)throws Exception;
        JSONObject graphql(String query,JSONObject variables)throws Exception;
        JSONObject get(String path)throws Exception;
        JSONArray list(String path)throws Exception;
        JSONObject put(String path,JSONObject body)throws Exception;
    }
    static JSONObject handle(JSONObject request,boolean github,String host,Transport api)throws Exception {
        String action=request.getString("action"),repo=request.getString("repository");
        if(!action.matches("work-board-(list|read|move)")||!repo.matches(github?"[A-Za-z0-9_.-]+/[A-Za-z0-9_.-]+":"[A-Za-z0-9_.-]+(?:/[A-Za-z0-9_.-]+)+")||repo.length()>500)throw invalid("Invalid board request");
        for(String part:repo.split("/"))if(part.equals(".")||part.equals(".."))throw invalid("Invalid board repository");
        if(request.has("provider")&&!request.getString("provider").equals(github?"github":"gitlab"))throw invalid("Board provider mismatch");
        NativeChatRequest.validateScope(request.getString("ref"),request.getString("file"));
        api.authorize(false);
        return github?github(request,repo,api):gitlab(request,repo,host,api);
    }
    private static Failure invalid(String text){return new Failure(text);}
    static void verifyGithubScopes(String requested,String granted)throws IOException {
        if(requested.isEmpty())return;java.util.Set<String> scopes=new java.util.HashSet<>(java.util.Arrays.asList(granted.split("[ ,]+")));
        boolean privateAccess=java.util.Arrays.asList(requested.split(" ")).contains("repo"),projects=java.util.Arrays.asList(requested.split(" ")).contains("project");
        if(!(privateAccess?scopes.contains("repo"):scopes.contains("repo")||scopes.contains("public_repo"))||projects&&!scopes.contains("project"))throw invalid("GitHub did not grant the requested repository and Projects access; reconnect and approve the selected permissions");
    }
    private static String text(JSONObject row,String key,int limit)throws Exception {Object value=row.get(key);if(!(value instanceof String)||((String)value).length()>limit)throw invalid("Invalid board "+key);return(String)value;}
    private static String id(JSONObject row,String key)throws Exception {String value=text(row,key,200);if(!value.matches("[A-Za-z0-9_+/=.-]{1,200}")||value.contains(".."))throw invalid("Invalid board identifier");return value;}
    private static long number(JSONObject row,String key)throws Exception {Object raw=row.get(key);if(!(raw instanceof Number))throw invalid("Invalid numeric board identifier");long value=((Number)raw).longValue();if(value<1||value>9007199254740991L||((Number)raw).doubleValue()!=value)throw invalid("Invalid numeric board identifier");return value;}
    private static String cursor(JSONObject request)throws Exception {if(!request.has("cursor")||request.isNull("cursor"))return null;String value=text(request,"cursor",1024);if(value.isEmpty()||value.matches("(?s).*[\\x00-\\x1f\\x7f].*"))throw invalid("Invalid board cursor");return value;}
    private static JSONObject paging(JSONObject connection,int limit,String previous)throws Exception {
        if(connection.getJSONArray("nodes").length()>limit)throw invalid("Board page exceeds its limit");JSONObject info=connection.getJSONObject("pageInfo");boolean more=info.getBoolean("hasNextPage");JSONObject result=new JSONObject().put("hasMore",more).put("warnings",new JSONArray());
        if(more){String next=cursor(new JSONObject().put("cursor",info.get("endCursor")));if(next==null||next.equals(previous))throw invalid("Invalid board pagination");result.put("cursor",next);}return result;
    }
    private static String githubUrl(JSONObject project)throws Exception {String value=text(project,"url",1000);URI url=new URI(value);if(!"https".equals(url.getScheme())||!"github.com".equals(url.getHost())||url.getPort()!=-1||url.getUserInfo()!=null||url.getQuery()!=null||url.getFragment()!=null||!url.getPath().matches("/(?:users|orgs)/[A-Za-z0-9-]+/projects/[1-9][0-9]*"))throw invalid("Invalid GitHub project URL");return value;}
    private static boolean repository(JSONObject row,String repo){return row!=null&&repo.equalsIgnoreCase(row.optString("nameWithOwner"));}
    private static JSONArray assignees(JSONArray rows,String key)throws Exception {JSONArray result=new JSONArray();if(rows==null)return result;for(int i=0;i<Math.min(10,rows.length());i++){JSONObject row=rows.optJSONObject(i);String login=row==null?"":row.optString(key);if(login.matches("[A-Za-z0-9][A-Za-z0-9_.-]{0,99}"))result.put(login);}return result;}
    private static JSONObject github(JSONObject request,String repo,Transport api)throws Exception {
        String action=request.getString("action"),after=cursor(request);String[] names=repo.split("/");
        if(action.equals("work-board-list")){
            JSONObject value=api.graphql("query($owner:String!,$name:String!,$cursor:String){repository(owner:$owner,name:$name){projectsV2(first:20,after:$cursor){nodes{id title number url closed} pageInfo{hasNextPage endCursor}}}}",new JSONObject().put("owner",names[0]).put("name",names[1]).put("cursor",after==null?JSONObject.NULL:after)).getJSONObject("repository").getJSONObject("projectsV2");
            JSONObject result=paging(value,20,after);JSONArray rows=value.getJSONArray("nodes"),boards=new JSONArray();for(int i=0;i<rows.length();i++){JSONObject row=rows.getJSONObject(i);number(row,"number");if(!row.getBoolean("closed"))boards.put(new JSONObject().put("id",id(row,"id")).put("title",text(row,"title",1024)).put("url",githubUrl(row)));}return result.put("boards",boards);
        }
        String boardId=id(request,"boardId");JSONObject board=githubRead(request,repo,api);
        if(action.equals("work-board-read"))return board;
        String itemId=id(request,"itemId"),option=text(request,"optionId",200);boolean known=false;JSONArray columns=board.getJSONArray("columns");for(int i=0;i<columns.length();i++)known|=option.equals(columns.getJSONObject(i).getString("id"));if(!known)throw invalid("Project status changed; refresh the board");
        JSONObject item=api.graphql("query($id:ID!){node(id:$id){... on ProjectV2Item{id project{id} fieldValues(first:100){nodes{... on ProjectV2ItemFieldSingleSelectValue{optionId field{... on ProjectV2SingleSelectField{id}}}} pageInfo{hasNextPage endCursor}} content{... on Issue{repository{nameWithOwner}} ... on PullRequest{repository{nameWithOwner}}}}}}",new JSONObject().put("id",itemId)).getJSONObject("node");
        if(!itemId.equals(item.optString("id"))||!boardId.equals(item.getJSONObject("project").optString("id"))||!repository(item.getJSONObject("content").optJSONObject("repository"),repo))throw invalid("Board item belongs to another project or repository");
        String fieldId=board.getString("fieldId");if(request.has("expectedColumnId")){JSONObject values=item.getJSONObject("fieldValues");if(values.getJSONObject("pageInfo").getBoolean("hasNextPage")||!status(values.getJSONArray("nodes"),fieldId).equals(text(request,"expectedColumnId",200)))throw invalid("Project item status changed; refresh before moving");}
        api.authorize(true);boolean clear=option.isEmpty();String operation=clear?"clearProjectV2ItemFieldValue":"updateProjectV2ItemFieldValue",inputType=clear?"ClearProjectV2ItemFieldValueInput":"UpdateProjectV2ItemFieldValueInput";
        JSONObject input=new JSONObject().put("projectId",boardId).put("itemId",itemId).put("fieldId",fieldId);if(!clear)input.put("value",new JSONObject().put("singleSelectOptionId",option));
        JSONObject updated=api.graphql("mutation($input:"+inputType+"!){"+operation+"(input:$input){projectV2Item{id}}}",new JSONObject().put("input",input)).getJSONObject(operation).getJSONObject("projectV2Item");if(!itemId.equals(updated.optString("id")))throw invalid("GitHub did not confirm the board move; refresh before retrying");return new JSONObject().put("updated",true).put("itemId",itemId).put("columnId",option);
    }
    private static String status(JSONArray values,String fieldId)throws Exception {if(values.length()>100)throw invalid("Invalid item field count");for(int i=0;i<values.length();i++){JSONObject value=values.optJSONObject(i);if(value!=null&&value.optJSONObject("field")!=null&&fieldId.equals(value.getJSONObject("field").optString("id")))return text(value,"optionId",200);}return "";}
    private static JSONObject githubRead(JSONObject request,String repo,Transport api)throws Exception {
        String boardId=id(request,"boardId"),after=request.getString("action").equals("work-board-move")?null:cursor(request);
        String query="query($id:ID!,$cursor:String){node(id:$id){... on ProjectV2{id title url repositories(first:100){nodes{nameWithOwner}} fields(first:100){nodes{... on ProjectV2SingleSelectField{id name options{id name}}} pageInfo{hasNextPage endCursor}} items(first:50,after:$cursor){nodes{id fieldValues(first:100){nodes{... on ProjectV2ItemFieldSingleSelectValue{optionId field{... on ProjectV2SingleSelectField{id}}}} pageInfo{hasNextPage endCursor}} content{__typename ... on Issue{number title repository{nameWithOwner} assignees(first:10){nodes{login}}} ... on PullRequest{number title repository{nameWithOwner} assignees(first:10){nodes{login}}}}} pageInfo{hasNextPage endCursor}}}}}";
        JSONObject project=api.graphql(query,new JSONObject().put("id",boardId).put("cursor",after==null?JSONObject.NULL:after)).getJSONObject("node");if(!boardId.equals(project.optString("id")))throw invalid("GitHub project identity changed");
        boolean linked=false;JSONArray repos=project.getJSONObject("repositories").getJSONArray("nodes");if(repos.length()>100)throw invalid("Invalid project repository count");for(int i=0;i<repos.length();i++)linked|=repository(repos.optJSONObject(i),repo);if(!linked)throw invalid("Project is not linked to the active repository");
        JSONArray fields=project.getJSONObject("fields").getJSONArray("nodes");if(fields.length()>100)throw invalid("Invalid project field count");JSONObject field=null;for(int i=0;i<fields.length();i++){JSONObject row=fields.optJSONObject(i);if(row!=null&&(request.has("fieldId")?id(request,"fieldId").equals(row.optString("id")):"Status".equals(row.optString("name"))))field=row;}if(field==null)throw invalid("Choose a single-select project status field");
        String fieldId=id(field,"id");JSONArray options=field.getJSONArray("options"),columns=new JSONArray().put(new JSONObject().put("id","").put("title","No status"));if(options.length()>100)throw invalid("Invalid project option count");for(int i=0;i<options.length();i++){JSONObject option=options.getJSONObject(i);columns.put(new JSONObject().put("id",text(option,"id",200)).put("title",text(option,"name",200)));}
        JSONObject result=paging(project.getJSONObject("items"),50,after);JSONArray warnings=result.getJSONArray("warnings");if(project.getJSONObject("fields").getJSONObject("pageInfo").getBoolean("hasNextPage"))warnings.put("Project fields are limited to 100");JSONArray rows=project.getJSONObject("items").getJSONArray("nodes"),items=new JSONArray();
        for(int i=0;i<rows.length();i++){JSONObject row=rows.getJSONObject(i),content=row.optJSONObject("content");if(content==null||!repository(content.optJSONObject("repository"),repo))continue;String kind=content.getString("__typename");if(!kind.equals("Issue")&&!kind.equals("PullRequest"))throw invalid("Invalid project item type");long num=number(content,"number");String column=status(row.getJSONObject("fieldValues").getJSONArray("nodes"),fieldId);boolean valid=false;for(int j=0;j<columns.length();j++)valid|=column.equals(columns.getJSONObject(j).getString("id"));if(!valid)throw invalid("Invalid project item status");if(row.getJSONObject("fieldValues").getJSONObject("pageInfo").getBoolean("hasNextPage"))warnings.put("Some project item fields were truncated");items.put(new JSONObject().put("id",id(row,"id")).put("title",text(content,"title",1024)).put("number",num).put("kind",kind.equals("Issue")?"issue":"pull").put("repository",repo).put("url","https://github.com/"+repo+"/"+(kind.equals("Issue")?"issues":"pull")+"/"+num).put("columnId",column).put("assignees",assignees(content.optJSONObject("assignees")==null?null:content.getJSONObject("assignees").optJSONArray("nodes"),"login")));}
        return result.put("id",boardId).put("title",text(project,"title",1024)).put("url",githubUrl(project)).put("fieldId",fieldId).put("columns",columns).put("items",items);
    }
    private static boolean contains(JSONArray values,String label)throws Exception {for(int i=0;i<values.length();i++)if(label.equals(values.getString(i)))return true;return false;}
    private static int page(JSONObject request)throws Exception {if(!request.has("page"))return 1;long value=number(request,"page");if(value>20)throw invalid("Board page exceeds its limit");return(int)value;}
    private static JSONObject gitlab(JSONObject request,String repo,String host,Transport api)throws Exception {
        String action=request.getString("action");int page=page(request);JSONObject metadata=api.get("/projects/"+URLEncoder.encode(repo,"UTF-8"));long projectId=number(metadata,"id");if(!repo.equals(metadata.optString("path_with_namespace")))throw invalid("GitLab project identity changed");String path="/projects/"+projectId;
        if(action.equals("work-board-list")){JSONArray rows=api.list(path+"/boards?per_page=20&page="+page);if(rows.length()>20)throw invalid("Invalid board page size");JSONArray boards=new JSONArray();for(int i=0;i<rows.length();i++){JSONObject row=rows.getJSONObject(i);long id=number(row,"id");boards.put(new JSONObject().put("id",id).put("title",text(row,"name",1024)).put("url",host+"/"+repo+"/-/boards/"+id));}return gitlabPaging(rows.length(),20,page).put("boards",boards);}
        long boardId=number(request,"boardId");JSONObject board=api.get(path+"/boards/"+boardId);if(number(board,"id")!=boardId||board.optJSONObject("project")!=null&&number(board.getJSONObject("project"),"id")!=projectId)throw invalid("GitLab board identity changed");
        if(!board.isNull("assignee")||!board.isNull("milestone")||!board.isNull("iteration")||!board.isNull("weight")||board.optJSONArray("labels")!=null&&board.getJSONArray("labels").length()>0)throw invalid("Open this scoped board in GitLab; unscoped label boards are supported here");
        JSONArray lists=board.getJSONArray("lists");if(lists.length()>100)throw invalid("Too many GitLab board lists");List<JSONObject> sorted=new ArrayList<>();for(int i=0;i<lists.length();i++){JSONObject row=lists.getJSONObject(i);number(row,"id");JSONObject label=row.optJSONObject("label");if(label==null)throw invalid("Open this board in GitLab; only label lists are supported");String name=text(label,"name",255);if(name.isEmpty()||name.contains(",")||name.matches("(?s).*[\\x00-\\x1f\\x7f].*"))throw invalid("Unsupported board label");sorted.add(row);}sorted.sort((a,b)->Integer.compare(a.optInt("position"),b.optInt("position")));
        JSONArray columns=new JSONArray();if(!board.optBoolean("hide_backlog_list"))columns.put(new JSONObject().put("id","open").put("title","Open"));for(JSONObject row:sorted)columns.put(new JSONObject().put("id",number(row,"id")).put("title",row.getJSONObject("label").getString("name")));if(!board.optBoolean("hide_closed_list"))columns.put(new JSONObject().put("id","closed").put("title","Closed"));
        if(action.equals("work-board-move")){
            long itemId=number(request,"itemId");Object target=request.get("listId"),source=request.opt("fromListId");String targetName="",sourceName="";boolean known=target.equals("open")&&!board.optBoolean("hide_backlog_list")||target.equals("closed")&&!board.optBoolean("hide_closed_list"),sourceKnown=source==null||source==JSONObject.NULL||source.equals("open")||source.equals("closed");
            if(target instanceof Number)number(request,"listId");else if(!(target instanceof String))throw invalid("Invalid board list identifier");
            if(source instanceof Number)number(request,"fromListId");else if(source!=null&&source!=JSONObject.NULL&&!(source instanceof String))throw invalid("Invalid source list identifier");
            for(JSONObject row:sorted){if(target instanceof Number&&((Number)target).longValue()==number(row,"id")){known=true;targetName=row.getJSONObject("label").getString("name");}if(source instanceof Number&&((Number)source).longValue()==number(row,"id")){sourceKnown=true;sourceName=row.getJSONObject("label").getString("name");}}
            if(!known||!sourceKnown)throw invalid("Board lists changed; refresh before moving");JSONObject issue=api.get(path+"/issues/"+itemId);validateIssue(issue,projectId,itemId);if(request.has("expectedUpdatedAt")&&!text(request,"expectedUpdatedAt",100).equals(issue.optString("updated_at")))throw invalid("Task changed; refresh before moving");JSONArray labels=issue.getJSONArray("labels");if(!sourceName.isEmpty()&&!contains(labels,sourceName))throw invalid("Task left the source list; refresh before moving");
            List<String> remove=new ArrayList<>();if(target.equals("open")){for(JSONObject row:sorted){String name=row.getJSONObject("label").getString("name");if(contains(labels,name))remove.add(name);}}else if(!sourceName.isEmpty()&&!sourceName.equals(targetName))remove.add(sourceName);
            JSONObject body=new JSONObject();if(!targetName.isEmpty())body.put("add_labels",targetName);if(!remove.isEmpty())body.put("remove_labels",String.join(",",remove));if(target.equals("closed"))body.put("state_event","close");else if(issue.getString("state").equals("closed"))body.put("state_event","reopen");api.authorize(true);
            JSONObject result=api.put(path+"/issues/"+itemId,body);validateIssue(result,projectId,itemId);JSONArray updated=result.getJSONArray("labels");if(!result.getString("state").equals(target.equals("closed")?"closed":"opened")||!targetName.isEmpty()&&!contains(updated,targetName))throw invalid("GitLab did not confirm the board move; refresh before retrying");for(String label:remove)if(contains(updated,label))throw invalid("GitLab did not confirm removed labels; refresh before retrying");return new JSONObject().put("updated",true).put("itemId",itemId).put("columnId",target);
        }
        JSONArray rows=api.list(path+"/issues?state=all&scope=all&order_by=updated_at&sort=desc&per_page=50&page="+page);if(rows.length()>50)throw invalid("Invalid board issue page size");JSONArray items=new JSONArray();for(int i=0;i<rows.length();i++){JSONObject row=rows.getJSONObject(i);long iid=number(row,"iid");validateIssue(row,projectId,iid);JSONArray columnIds=new JSONArray();if(row.getString("state").equals("closed")){if(!board.optBoolean("hide_closed_list"))columnIds.put("closed");}else{for(JSONObject list:sorted)if(contains(row.getJSONArray("labels"),list.getJSONObject("label").getString("name")))columnIds.put(number(list,"id"));if(columnIds.length()==0&&!board.optBoolean("hide_backlog_list"))columnIds.put("open");}if(columnIds.length()==0)continue;items.put(new JSONObject().put("id",iid).put("title",text(row,"title",1024)).put("number",iid).put("kind","issue").put("repository",repo).put("url",host+"/"+repo+"/-/issues/"+iid).put("columnId",columnIds.get(0)).put("columnIds",columnIds).put("updatedAt",row.optString("updated_at")).put("assignees",assignees(row.optJSONArray("assignees"),"username")));}
        return gitlabPaging(rows.length(),50,page).put("id",boardId).put("title",text(board,"name",1024)).put("url",host+"/"+repo+"/-/boards/"+boardId).put("columns",columns).put("items",items);
    }
    private static void validateIssue(JSONObject issue,long projectId,long iid)throws Exception {if(number(issue,"iid")!=iid||number(issue,"project_id")!=projectId||!issue.optString("state").matches("opened|closed"))throw invalid("GitLab returned another issue identity");JSONArray labels=issue.getJSONArray("labels");if(labels.length()>1000)throw invalid("Too many issue labels");for(int i=0;i<labels.length();i++)if(!(labels.get(i)instanceof String))throw invalid("Invalid issue labels");}
    private static JSONObject gitlabPaging(int count,int limit,int page)throws Exception {JSONObject result=new JSONObject().put("hasMore",count==limit&&page<20).put("warnings",new JSONArray());if(count==limit){if(page<20)result.put("nextPage",page+1);else result.getJSONArray("warnings").put("Board results reached their page limit; open the complete board on GitLab");}return result;}
}
